# Math RAG corpus. OpenStax math books on GitHub are CC BY-NC-SA (NOT commercial) -> excluded. Use English Wikipedia (CC BY-SA 4.0, commercial use OK
# with attribution + share-alike): competition-math topics, plain-text extracts, ~900-char chunks.
import json,urllib.request,urllib.parse,re,time
T="""Vieta's formulas|Chinese remainder theorem|Fermat's little theorem|Euler's theorem|Euler's totient function|Modular arithmetic|Quadratic residue|Legendre symbol|Lifting-the-exponent lemma|Diophantine equation|Pell's equation|Pythagorean triple|Greatest common divisor|Least common multiple|Divisor function|Prime factorization|Fundamental theorem of arithmetic|Wilson's theorem|Floor and ceiling functions|Legendre's formula|Binomial coefficient|Binomial theorem|Pascal's triangle|Stars and bars (combinatorics)|Inclusion–exclusion principle|Pigeonhole principle|Catalan number|Derangement|Stirling numbers of the second kind|Burnside's lemma|Generating function|Recurrence relation|Fibonacci sequence|Linear recurrence with constant coefficients|Expected value|Linearity of expectation|Conditional probability|Geometric distribution|Markov chain|Random walk|Arithmetic progression|Geometric progression|Telescoping series|AM–GM inequality|Cauchy–Schwarz inequality|Jensen's inequality|Triangle inequality|Polynomial|Roots of unity|Complex number|De Moivre's formula|Euler's formula|Rational root theorem|Polynomial remainder theorem|Descartes' rule of signs|Newton's identities|Symmetric polynomial|Logarithm|Exponentiation|Quadratic equation|Quadratic formula|Cubic equation|Absolute value|Function composition|Inverse function|Trigonometric functions|List of trigonometric identities|Law of sines|Law of cosines|Heron's formula|Area of a triangle|Stewart's theorem|Ptolemy's theorem|Power of a point|Inscribed angle|Angle bisector theorem|Ceva's theorem|Menelaus's theorem|Incircle and excircles|Circumcircle|Similarity (geometry)|Pythagorean theorem|Shoelace formula|Pick's theorem|Coordinate geometry|Conic section|Ellipse|Parabola|Hyperbola|Analytic geometry|Vector (mathematics and physics)|Dot product|Cross product|Determinant|Matrix (mathematics)|Tetrahedron|Volume|Sphere|Cone|Cylinder|Polyhedron|Regular polygon|Hexagon|Trapezoid|Rhombus|Rectangle|Square|Circle|Arc length|Sector (geometry)|Rotation (mathematics)|Reflection (mathematics)|Base (exponentiation)|Positional notation|Binary number|Digit sum|Divisibility rule|Palindromic number|Perfect number|Triangular number|Permutation|Combination|Combinatorics|Graph theory|Hamiltonian path|Tree (graph theory)|Invariant (mathematics)|Mathematical induction|Parity (mathematics)|Lattice path|Calculus|Derivative|Integral|Limit (mathematics)|Taylor series|Sequence|Series (mathematics)|Golden ratio|Euclidean algorithm|Extended Euclidean algorithm|Order (group theory)|Primitive root modulo n|Mersenne prime|Multiplicative inverse|Functional equation|Cauchy's functional equation|Periodic function|Rational number|Irrational number|Partial fraction decomposition|Sum of squares function|Probability""".split('|')
C=[]
for t in T:
    u='https://en.wikipedia.org/w/api.php?'+urllib.parse.urlencode({'action':'query','prop':'extracts|info','explaintext':1,'redirects':1,'titles':t,'format':'json','inprop':'url'})
    try: p=list(json.load(urllib.request.urlopen(urllib.request.Request(u,headers={'User-Agent':'gdp-research/1.0'}),timeout=60))['query']['pages'].values())[0]
    except Exception as e: print('fail',t,e); continue
    x=re.split(r'\n== (See also|References|External links|Notes|Further reading) ==',p.get('extract',''))[0]
    paras=[s.strip() for s in x.split('\n') if len(s.strip())>80]; buf=''
    for s in paras:
        if len(buf)+len(s)>900 and buf: C.append({'title':p['title'],'url':p.get('fullurl'),'license':'CC BY-SA 4.0','text':buf}); buf=''
        buf+=s+'\n'
    if buf: C.append({'title':p['title'],'url':p.get('fullurl'),'license':'CC BY-SA 4.0','text':buf})
    time.sleep(.2)
with open('chunks.jsonl','w') as f:
    for c in C: f.write(json.dumps(c,ensure_ascii=False)+'\n')
print(len(T),'titles',len(C),'chunks')
